import random
import string
from typing import List, Tuple

# Generator for valid and interesting numeric strings for bases used in stubs: 0,2,8,10,16,36
# Aim: produce mostly valid inputs with variation to exercise edge cases of SnortStrtol/Strtoul/StrToU32
# Returned bytes form a NUL-terminated like buffer when C++ constructs std::string (no NUL needed),
# but we will avoid embedded NULs as they would truncate C strings in the targets.

_WHITESPACE = [" ", "\t", "\n", "\r", "\v", "\f"]
_DIGITS_36 = string.digits + string.ascii_lowercase

# Precompute digit maps for bases 2..36
_BASE_DIGITS = {b: _DIGITS_36[:b] for b in range(2, 37)}

def _maybe_ws(rng: random.Random) -> str:
    # 0..6 leading whitespace characters chosen from C isspace set
    return "".join(rng.choices(_WHITESPACE, k=rng.randint(0, 6)))

def _sign_for(base: int, allow_negative: bool, rng: random.Random) -> str:
    # For StrToU32, negative should be rejected; we still produce some negatives to exercise error path.
    if not allow_negative:
        return "" if rng.random() < 0.9 else "-"  # 10% negative to trigger error path
    # For strtol we want both + and - cases
    p = rng.random()
    if p < 0.4:
        return "-"
    elif p < 0.8:
        return "+"
    else:
        return ""

def _prefix_for(base: int, rng: random.Random) -> str:
    # For base 0, prefix can drive autodetection. For explicit bases, include optional prefixes sometimes.
    if base == 0:
        # choose among 0x hex, 0 octal, none, 0b (some libs parse with base 0? Typically not, but harmless)
        choice = rng.random()
        if choice < 0.33:
            return "0x"
        elif choice < 0.66:
            return "0"
        else:
            return ""
    if base == 16 and rng.random() < 0.6:
        return "0x"
    if base == 2 and rng.random() < 0.3:
        return "0b"  # Not standard for strto*, but some implementations ignore; keep rare
    return ""

def _digits_for_value(val: int, base: int) -> str:
    # Encode value in given base using lowercase digits
    if base == 0:
        # Choose a base appropriate to magnitude: prefer decimal
        base = 10
    if val == 0:
        return "0"
    s = []
    b = base
    while val > 0:
        val, rem = divmod(val, b)
        s.append(_DIGITS_36[rem])
    return "".join(reversed(s))

def _rand_number_str(base: int, max_digits: int, rng: random.Random, allow_leading_zeros: bool = True) -> str:
    digits = _BASE_DIGITS[base if base != 0 else 10]
    n = rng.randint(1, max(1, max_digits))
    s = "".join(rng.choice(digits) for _ in range(n))
    if allow_leading_zeros and rng.random() < 0.5:
        s = ("0" * rng.randint(1, 6)) + s
    return s

def _make_valid_numeric(base: int, for_unsigned: bool, rng: random.Random) -> str:
    # Produce a string likely to be fully valid for the chosen base
    ws = _maybe_ws(rng)
    sign = _sign_for(base, allow_negative=not for_unsigned, rng=rng)
    prefix = _prefix_for(base, rng)

    if base == 0:
        # Select actual base realization
        actual = rng.choice([10, 8, 16])
    else:
        actual = base

    # Mix extremes: small, large within 32-bit, and larger to test strtoul overflow handling
    mode = rng.random()
    if mode < 0.3:
        # small values
        value = rng.randint(0, 1024)
        digits = _digits_for_value(value, actual)
    elif mode < 0.7:
        # within 32-bit range
        value = rng.randint(0, 0xFFFFFFFF)
        digits = _digits_for_value(value, actual)
    else:
        # potentially overflow 32-bit but fit within Python int; exercise ERANGE in StrToU32
        value = rng.randint(0x1_0000_0000, 0x1FFF_FFFF_FFFF)
        digits = _digits_for_value(value, actual)

    if rng.random() < 0.4:
        # randomly generate dense digit strings instead of exact value representation
        digits = _rand_number_str(actual if actual != 0 else 10, max_digits=32, rng=rng)

    # Optionally append trailing junk for strtol/strtoul (endptr should stop early)
    trailer = ""
    if rng.random() < 0.5:
        # allowed to have trailing spaces; sometimes mix with letters not valid in base
        trail_ws = _maybe_ws(rng)
        # 30% add invalid char to force early stop
        invalid = ""
        if rng.random() < 0.3:
            # pick a char outside the base's digit set
            candidates = [c for c in (string.punctuation + string.ascii_letters) if c.lower() not in _BASE_DIGITS.get(actual, _BASE_DIGITS[10])]
            if candidates:
                invalid = rng.choice(candidates)
        trailer = trail_ws + invalid + _maybe_ws(rng)

    return ws + sign + prefix + digits + trailer

def _make_edge_cases(base: int, for_unsigned: bool) -> List[str]:
    # Deterministic interesting cases per base
    cases = []
    # Empty and whitespace only
    cases.append("")
    cases.append("   \t\n")
    # Just sign
    cases.append("-")
    cases.append("+")
    # Zero forms
    if base in (0, 8, 10, 16):
        cases.extend(["0", "00", "0000"]) 
    if base in (0, 16):
        cases.extend(["0x", "0x0", "0xdeadbeef", "0xFFFFFFFF"]) 
    if base in (0, 8):
        cases.extend(["0777", "01234567"]) 
    if base in (0, 2):
        cases.extend(["0b", "0b101010"]) 
    if base in (10, 0):
        cases.extend(["18446744073709551615", "4294967295", "2147483647", "-2147483648"]) 
    if base == 36:
        cases.extend(["zz", "zzzzzz", "deadbeef".replace("e","e")])
    if for_unsigned:
        cases.append("-1")
    return cases

def _choose_base(rng: random.Random) -> int:
    return rng.choice([0, 2, 8, 10, 16, 36])

def _pick_distribution(rng: random.Random) -> str:
    return rng.choice(["valid", "edge", "mixed"])  # simple distribution

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    base = _choose_base(rng)

    # Decide which target we bias towards; influences sign policy
    target = rng.choice(["strtol", "strtoul", "strtou32"])
    for_unsigned = target != "strtol"

    mode = _pick_distribution(rng)
    if mode == "edge":
        s = rng.choice(_make_edge_cases(base, for_unsigned))
    elif mode == "mixed":
        # concatenate multiple valid numbers separated by spaces to test endptr behavior
        parts = []
        count = rng.randint(2, 4)
        for _ in range(count):
            parts.append(_make_valid_numeric(base, for_unsigned, rng))
        sep = rng.choice([" ", "\t", ",", ";"]) * rng.randint(1, 3)
        s = sep.join(parts)
    else:
        s = _make_valid_numeric(base, for_unsigned, rng)

    # Ensure no embedded NULs and bound length
    s = s.replace("\x00", "")
    # Keep under 4096 bytes
    if len(s) > 4000:
        s = s[:4000]

    return s.encode("ascii", errors="ignore")
